/// <summary>
/// Controller class for the METCoverNote report
/// </summary>
class METCoverNoteController extends SrsReportRunController
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <returns>New Controller Object</returns>
    public static METCoverNoteController construct(Args _args)
    {
        METCoverNoteController controller = new METCoverNoteController();
        controller.parmArgs(_args);
        controller.parmReportName(ssrsReportStr(METCoverNoteReport, Design));
        controller.parmShowDialog(false);

        return controller;
    }

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    container                       conShipmentId   = str2con(_args.parm());
    MetShipmentId                   shipmentID;
    METCoverNoteContract            contract;
   
    for (int i =1; conLen(conShipmentId) >= i; i++)
    {
        METCoverNoteController controller = METCoverNoteController::construct(_args);
        contract    = controller.parmReportContract().parmRdpContract() as METCoverNoteContract;
        shipmentID  = conPeek(conShipmentId, i);
        
        contract.parmShipmentID(shipmentID);
    
        controller.startOperation();
    }
}
